pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // 1. Bound the amount to a reasonable non-zero range to avoid revert on insufficient funds and keep domain wide
        bound(amount, 1, 100 ether);

        // 2. Setup: fund the contract with the fuzzed amount
        vm.deal(address(this), amount);
        (bool funded,) = address(c).call{value: amount}("");
        require(funded, "funding failed");

        // 3. Record owner balance before withdrawAll
        uint256 ownerBefore = c.owner().balance;
        uint256 contractBalanceBefore = address(c).balance;

        // 4. Execute withdrawAll as owner (this is already owner)
        c.withdrawAll();

        // 5. Calculate actual owner balance increase
        uint256 ownerAfter = c.owner().balance;
        uint256 ownerIncrease = ownerAfter - ownerBefore;

        // 6. Assert: owner increase equals the full contract balance before withdrawal
        assertTrue(ownerIncrease == contractBalanceBefore);
    }
}

