pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // Bound amount to available balance to avoid reverts due to insufficient funds
        uint256 initBal = address(c).balance;
        amount = bound(amount, 0, initBal);

        // Record pre-state
        uint256 preOwnerBal = c.owner().balance;
        uint256 preContractBal = address(c).balance;

        // Owner calls withdraw
        vm.prank(c.owner());
        c.withdraw(amount);

        // Post-state
        uint256 postOwnerBal = c.owner().balance;
        uint256 postContractBal = address(c).balance;

        // Conservation of ETH: preContractBal + preOwnerBal == postContractBal + postOwnerBal
        assertTrue(preContractBal + preOwnerBal == postContractBal + postOwnerBal);
    }
}

